node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs = require("fs")
const fail = (m) => { console.error(m); process.exit(1) }
const rd = (f) => { try { return fs.readFileSync(f, "utf8") } catch (e) { return "" } }
const strip = (s) => s.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/^\s*\/\/.*$/gm, " ").replace(/\s+/g, " ")
import("./lib/ui/modal-stack.ts").then((m) => {
  let told = 0
  const stop = m.subscribeModals(() => { told += 1 })
  if (m.anyModalOpen()) fail("the modal stack reports something open before anything opened")
  const outer = Symbol("console"), inner = Symbol("drawer")
  m.pushModal(outer)
  if (!m.anyModalOpen() || told !== 1) fail("opening a modal does not publish that the page is covered, so ambient chrome cannot know to hold still")
  m.pushModal(inner)
  if (m.isTopModal(outer) || !m.isTopModal(inner)) fail("the innermost modal is not the topmost one, so Esc and Tab would drive two dialogs at once")
  m.popModal(inner)
  if (!m.anyModalOpen() || m.modalDepth() !== 1) fail("an inner modal closing reports the page clear while the outer one is still covering it")
  m.popModal(outer)
  if (m.anyModalOpen() || m.modalDepth() !== 0 || told !== 4) fail("closing the last modal does not publish that the page is clear again, so the pause would never lift")
  m.popModal(outer)
  if (told !== 4) fail("popping an id that is not on the stack still notifies, so a racing unmount can announce a clear page that is still covered")
  stop()

  const dialog = strip(rd("components/ui/dialog.tsx"))
  if (!dialog) fail("actual shared Dialog is missing")

  if (/const dialogStack/.test(dialog)) fail("components/ui/dialog.tsx keeps a private stack again, so opens and closes stop reaching subscribers and the ticker goes back to rotating under the console")
  if (!/pushModal\(id\)/.test(dialog) || !/popModal\(id\)/.test(dialog)) fail("the shared Dialog no longer publishes its opens and closes to the modal stack")
  if (!/isTopModal\(id\)/.test(dialog)) fail("the shared Dialog no longer asks the stack which dialog is topmost")
  if (!/modalDepth\(\) === 0/.test(dialog)) fail("the scroll lock no longer releases at depth zero, so a nested dialog closing unlocks the page under the one still open")
  process.exit(0)
}).catch((e) => fail("the modal stack could not be loaded: " + e.message))'
